<template x-if="['add','edit'].includes(modal)">
    <form @submit.prevent="saveOlt()" class="form-stack">
        <fieldset :disabled="busy" class="form-stack min-w-0 border-0 p-0">
        <p class="muted">Hubungkan OLT melalui jaringan manajemen. Password dan community disimpan terenkripsi.</p>
        <div class="notice" x-show="modal==='add' && quotaFull">Kuota OLT penuh. Form dapat disiapkan; hapus perangkat yang tidak digunakan atau tingkatkan paket sebelum menyimpan.</div>
        <label for="olt-name">Nama OLT<input id="olt-name" x-model="form.name" required maxlength="80" placeholder="Contoh: OLT23-BANDUNG" :aria-invalid="!!fieldError('name')" aria-describedby="olt-name-error"><small id="olt-name-error" class="field-error" x-show="fieldError('name')" x-text="fieldError('name')"></small></label>
        <div class="form-grid">
            <label>Mode koneksi<select aria-label="Mode koneksi" x-model="form.connection_mode"><option value="simulator" :disabled="form.chassis_type==='C1600'">Simulator</option><option value="real">Real - perangkat fisik</option></select></label>
            <label>Transport koneksi<select aria-label="Transport CLI" x-model="form.cli_transport" @change="changeOltTransport()"><option value="telnet" x-show="form.chassis_type!=='C1600'" :disabled="form.chassis_type==='C1600'">Telnet</option><option value="ssh" x-show="form.chassis_type!=='C1600'" :disabled="form.chassis_type==='C1600'">SSH</option><option value="https" x-show="form.chassis_type==='C1600'" :disabled="form.chassis_type!=='C1600'">HTTPS</option><option value="http" x-show="form.chassis_type==='C1600'" :disabled="form.chassis_type!=='C1600'">HTTP - jaringan manajemen internal</option></select></label>
            <label>Timeout koneksi (detik)<input aria-label="Timeout koneksi" type="number" min="1" max="30" x-model.number="form.connection_timeout" required></label>
            <label x-show="form.chassis_type!=='C1600'&&form.cli_transport==='ssh'">Fingerprint host SSH<input aria-label="Fingerprint host SSH" x-model="form.ssh_host_key_sha256" placeholder="SHA256:..." autocomplete="off"><small class="muted">Verifikasi fingerprint dari pengelola perangkat. Port koneksi CLI di bawah juga dipakai untuk SSH.</small></label>
            <label>Latitude OLT<input type="number" step="any" x-model="form.latitude" min="-90" max="90"></label><label>Longitude OLT<input type="number" step="any" x-model="form.longitude" min="-180" max="180"></label>
            <label for="olt-chassis">Tipe chassis<select id="olt-chassis" aria-label="Tipe chassis" x-model="form.chassis_type" @change="changeOltModel()"><option>C320</option><option>C300</option><option value="C1600">YOTC C1600 EPON</option></select><small class="field-error" x-show="fieldError('chassis_type')" x-text="fieldError('chassis_type')"></small></label>
            <label for="olt-ip">IP Address Private/Public<input id="olt-ip" x-model="form.ip_address" required placeholder="10.10.1.33 atau 103.110.8.1" :aria-invalid="!!fieldError('ip_address')" aria-describedby="olt-ip-error"><small id="olt-ip-error" class="field-error" x-show="fieldError('ip_address')" x-text="fieldError('ip_address')"></small></label>
            <label for="olt-telnet-port"><span x-text="'Port '+connectionLabel"></span><input id="olt-telnet-port" x-model.number="form.telnet_port" type="number" min="1" max="65535" required :aria-invalid="!!fieldError('telnet_port')" aria-describedby="olt-telnet-port-error"><small id="olt-telnet-port-error" class="field-error" x-show="fieldError('telnet_port')" x-text="fieldError('telnet_port')"></small></label>
            <label x-show="form.chassis_type!=='C1600'" for="olt-snmp-port">Port SNMP<input id="olt-snmp-port" x-model.number="form.snmp_port" type="number" min="1" max="65535" required :aria-invalid="!!fieldError('snmp_port')" aria-describedby="olt-snmp-port-error"><small id="olt-snmp-port-error" class="field-error" x-show="fieldError('snmp_port')" x-text="fieldError('snmp_port')"></small></label>
        </div>
        <fieldset class="credential-fields"><legend>Kredensial koneksi</legend><div class="form-grid">
            <label for="olt-user"><span x-text="'Username '+connectionLabel"></span><input id="olt-user" x-model="form.telnet_user" required maxlength="80" autocomplete="off" :aria-invalid="!!fieldError('telnet_user')" aria-describedby="olt-user-error"><small id="olt-user-error" class="field-error" x-show="fieldError('telnet_user')" x-text="fieldError('telnet_user')"></small></label>
            <label for="olt-password"><span x-text="'Password '+connectionLabel"></span><input id="olt-password" :aria-label="'Password '+connectionLabel" type="password" x-model="form.telnet_password" :required="modal==='add'" maxlength="255" autocomplete="new-password" :placeholder="modal==='edit'?'Kosongkan untuk mempertahankan':''" :aria-invalid="!!fieldError('telnet_password')" aria-describedby="olt-password-help olt-password-error"><small id="olt-password-help" class="muted" x-show="modal==='edit'" x-text="form.has_telnet_password?'Password tersimpan. Isi hanya untuk menggantinya.':'Password belum diatur.'"></small><small id="olt-password-error" class="field-error" x-show="fieldError('telnet_password')" x-text="fieldError('telnet_password')"></small></label>
            <label for="olt-community" class="full-width" x-show="form.chassis_type!=='C1600'">SNMP Community<input id="olt-community" aria-label="SNMP Community" type="password" x-model="form.snmp_community" :required="modal==='add'&&form.snmp_enabled" maxlength="255" autocomplete="new-password" :placeholder="modal==='edit'?'Kosongkan untuk mempertahankan':''" :aria-invalid="!!fieldError('snmp_community')" aria-describedby="olt-community-help olt-community-error"><small id="olt-community-help" class="muted" x-show="modal==='edit'" x-text="form.has_snmp_community?'Community tersimpan. Isi hanya untuk menggantinya.':'Community belum diatur.'"></small><small id="olt-community-error" class="field-error" x-show="fieldError('snmp_community')" x-text="fieldError('snmp_community')"></small></label>
        </div></fieldset>
        <fieldset class="credential-fields form-stack" x-show="form.chassis_type==='C1600'" :disabled="form.chassis_type!=='C1600'"><legend>Traffic PON melalui Telnet</legend>
            <label class="tag-checkboxes"><span><input type="checkbox" x-model="form.traffic_monitoring_enabled" :disabled="!trafficFormPorts().length"> Aktifkan monitoring traffic PON</span></label>
            <p class="muted small" x-show="!trafficFormPorts().length">Simpan OLT lalu sinkronkan inventaris terlebih dahulu agar port PON dapat dipilih.</p>
            <div class="form-stack" x-show="form.traffic_monitoring_enabled">
                <div class="form-grid">
                    <label for="traffic-telnet-port">Port Telnet traffic<input id="traffic-telnet-port" aria-label="Port Telnet traffic" type="number" min="1" max="65535" x-model.number="form.traffic_telnet_port" :required="form.chassis_type==='C1600'&&form.traffic_monitoring_enabled" :aria-invalid="!!fieldError('traffic_telnet_port')"><small class="field-error" x-show="fieldError('traffic_telnet_port')" x-text="fieldError('traffic_telnet_port')"></small></label>
                    <label for="traffic-telnet-user">Username Telnet traffic<input id="traffic-telnet-user" aria-label="Username Telnet traffic" x-model="form.traffic_telnet_user" maxlength="80" autocomplete="off"><small class="muted">Kosongkan jika perangkat hanya meminta password.</small><small class="field-error" x-show="fieldError('traffic_telnet_user')" x-text="fieldError('traffic_telnet_user')"></small></label>
                    <label for="traffic-telnet-password">Password Telnet traffic<input id="traffic-telnet-password" aria-label="Password Telnet traffic" type="password" x-model="form.traffic_telnet_password" maxlength="255" autocomplete="new-password" :required="form.chassis_type==='C1600'&&form.traffic_monitoring_enabled&&!form.has_traffic_telnet_password" :placeholder="form.has_traffic_telnet_password?'Kosongkan untuk mempertahankan':''" :aria-invalid="!!fieldError('traffic_telnet_password')"><small class="muted" x-show="form.has_traffic_telnet_password">Password tersimpan. Isi hanya untuk menggantinya.</small><small class="field-error" x-show="fieldError('traffic_telnet_password')" x-text="fieldError('traffic_telnet_password')"></small></label>
                    <label for="traffic-enable-password">Password mode privileged<input id="traffic-enable-password" aria-label="Password mode privileged" type="password" x-model="form.traffic_enable_password" maxlength="255" autocomplete="new-password" :placeholder="form.has_traffic_enable_password?'Kosongkan untuk mempertahankan':'Opsional: gunakan password Telnet'"><small class="muted" x-text="form.has_traffic_enable_password?'Password tersimpan. Isi hanya untuk menggantinya.':'Jika kosong, menggunakan password Telnet traffic.'"></small><small class="field-error" x-show="fieldError('traffic_enable_password')" x-text="fieldError('traffic_enable_password')"></small></label>
                </div>
                <fieldset class="credential-fields"><legend>Port PON yang dipantau</legend><p class="muted small">Pilih maksimal 4 PON yang sudah diuji.</p><div class="tag-checkboxes"><template x-for="port in trafficFormPorts()" :key="port.key"><label><input type="checkbox" :value="port.key" x-model="form.traffic_pon_ports" :disabled="form.traffic_pon_ports.length>=4&&!form.traffic_pon_ports.includes(port.key)"><span x-text="port.name"></span></label></template></div><small class="muted" x-text="form.traffic_pon_ports.length+' / 4 PON dipilih'"></small><small class="field-error" x-show="fieldError('traffic_pon_ports')" x-text="fieldError('traffic_pon_ports')"></small></fieldset>
                <p class="small muted">Traffic adalah total per port PON. Traffic per ONU belum tersedia. Mulai dari port yang sudah diuji.</p>
            </div>
            <p class="small muted">Menyimpan pengaturan ini hanya mengaktifkan pembacaan di NMS. Pengumpulan statistik pada OLT perlu diaktifkan terpisah oleh pengelola.</p>
            <div class="notice">Telnet tidak mengenkripsi password dan sesi. Gunakan hanya di jaringan manajemen internal yang aksesnya dibatasi.</div>
        </fieldset>
        <div class="notice" x-show="form.chassis_type==='C1600'">YOTC C1600 digunakan untuk monitoring. Pemasangan, konfigurasi ONU, reboot, backup, dan Web CLI belum tersedia.</div>
        <div class="notice" x-show="form.chassis_type==='C1600'&&form.cli_transport==='http'">HTTP tidak mengenkripsi password dan sesi. Gunakan hanya di jaringan manajemen internal yang aksesnya dibatasi.</div>
        <label class="tag-checkboxes" x-show="form.chassis_type!=='C1600'"><span><input type="checkbox" x-model="form.snmp_enabled"> Gunakan SNMP sebagai pelengkap uptime perangkat</span></label>
        <div class="notice" x-show="form.connection_mode==='real'">Mode REAL menghubungi IP OLT secara langsung. Timeout/login gagal akan ditampilkan sebagai error; tidak ada perpindahan otomatis ke simulator.</div>
        <div class="connection-test-controls"><label class="compact-field">Protokol pengujian<select aria-label="Protokol pengujian" x-model="testProtocol"><option value="cli" x-show="form.chassis_type!=='C1600'" :disabled="form.chassis_type==='C1600'">Telnet / SSH</option><option value="web" x-show="form.chassis_type==='C1600'" :disabled="form.chassis_type!=='C1600'">Web / HTTP(S)</option><option value="snmp" :disabled="form.chassis_type==='C1600'">SNMP v2c</option><option value="both" :disabled="form.chassis_type==='C1600'">CLI + SNMP</option></select></label><button class="btn secondary" type="button" @click="testConnection()" :disabled="busy">Test Connection</button></div>
        <p class="muted small">Test Connection selalu menguji perangkat nyata, termasuk saat form masih memilih simulator.</p>
        <div class="notice" x-show="connectionTest" role="status" x-text="connectionTest"></div>
        <label>Lokasi<input x-model="form.location" maxlength="120" placeholder="Area / alamat perangkat"></label>
        <div class="modal-actions"><button class="btn secondary" type="button" @click="closeModal()" :disabled="busy">Batal</button><button class="btn primary" type="submit" :disabled="busy" x-text="busy?'Memproses...':'Simpan OLT'"></button></div>
        </fieldset>
    </form>
</template>
